import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;
import com.sun.source.tree.*;import com.sun.source.util.*;
/** Parse and attribute every production input, but never emit mod bytecode. */
public class AttributeScanner {
 static String esc(Object o){return String.valueOf(o).replace("\\","\\\\").replace("\t","\\t").replace("\r","\\r").replace("\n","\\n");}
 public static void main(String[] args)throws Exception{
  Path root=Paths.get(args[0]).toAbsolutePath();List<String> paths=new ArrayList<>();try(java.util.stream.Stream<Path>w=Files.walk(root.resolve("src/main/java"))){w.filter(p->p.toString().endsWith(".java")).sorted().forEach(p->paths.add(p.toString()));}
  JavaCompiler compiler=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject> ds=new DiagnosticCollector<>();StandardJavaFileManager fm=compiler.getStandardFileManager(ds,null,StandardCharsets.UTF_8);
  JavacTask task=(JavacTask)compiler.getTask(null,fm,ds,Arrays.asList("-proc:none","-encoding","UTF-8","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8).trim(),"-Xmaxerrs","100000"),null,fm.getJavaFileObjectsFromStrings(paths));
  Trees trees=Trees.instance(task);SourcePositions pos=trees.getSourcePositions();List<CompilationUnitTree> units=new ArrayList<>();for(CompilationUnitTree u:task.parse())units.add(u);if(ds.getDiagnostics().stream().anyMatch(d->d.getKind()==Diagnostic.Kind.ERROR))throw new AssertionError("parse errors");task.analyze();System.err.println("Parsed "+units.size()+" units; native attribution diagnostics="+ds.getDiagnostics().stream().filter(d->d.getKind()==Diagnostic.Kind.ERROR).count());
  TypeElement item=task.getElements().getTypeElement("net.minecraft.item.Item");Set<String> names=new HashSet<>(Arrays.asList("getItemAttributeModifiers","getAttributeModifiers","getModifiers"));
  for(CompilationUnitTree u:units){String rel=root.relativize(Paths.get(u.getSourceFile().toUri())).toString(),source=u.getSourceFile().getCharContent(true).toString();new TreePathScanner<Void,Void>(){
   void row(String kind,Tree t,Element e,String extra){long s=pos.getStartPosition(u,t),end=pos.getEndPosition(u,t);if(s<0||end<s)return;System.out.println(String.join("\t",esc(kind),esc(rel),""+u.getLineMap().getLineNumber(s),""+s,""+end,esc(e==null?null:e.getKind()),esc(e==null?null:e.getEnclosingElement()),esc(e),esc(extra),Base64.getEncoder().encodeToString(source.substring((int)s,(int)end).getBytes(StandardCharsets.UTF_8))));}
   @Override public Void visitClass(ClassTree t,Void p){Element e=trees.getElement(getCurrentPath());if(e instanceof TypeElement&&task.getTypes().isSubtype(e.asType(),item.asType()))row("item-class",t,e,((TypeElement)e).getSuperclass().toString());return super.visitClass(t,p);}
   @Override public Void visitMethod(MethodTree t,Void p){if(names.contains(t.getName().toString())){Element e=trees.getElement(getCurrentPath());List<String> overridden=new ArrayList<>();if(e instanceof ExecutableElement&&e.getEnclosingElement() instanceof TypeElement)for(Element m:task.getElements().getAllMembers(item))if(m instanceof ExecutableElement&&task.getElements().overrides((ExecutableElement)e,(ExecutableElement)m,(TypeElement)e.getEnclosingElement()))overridden.add(m.toString());row("declaration",t,e,String.join(";",overridden));}return super.visitMethod(t,p);}
   @Override public Void visitMethodInvocation(MethodInvocationTree t,Void p){String name=t.getMethodSelect() instanceof MemberSelectTree?((MemberSelectTree)t.getMethodSelect()).getIdentifier().toString():t.getMethodSelect().toString();if(names.contains(name)){Element e=trees.getElement(new TreePath(getCurrentPath(),t.getMethodSelect()));TreePath cp=getCurrentPath();while(cp!=null&&!(cp.getLeaf() instanceof ClassTree))cp=cp.getParentPath();row("call",t,e,cp==null?"":trees.getElement(cp).toString());}return super.visitMethodInvocation(t,p);}
  }.scan(u,null);}
  try(java.io.PrintWriter out=new java.io.PrintWriter(args[2],"UTF-8")){for(Diagnostic<? extends JavaFileObject>d:ds.getDiagnostics())if(d.getKind()==Diagnostic.Kind.ERROR){String rel=d.getSource()==null?"null":root.relativize(Paths.get(d.getSource().toUri())).toString();out.println(esc(rel)+"\t"+d.getLineNumber()+"\t"+esc(d.getCode())+"\t"+esc(d.getMessage(Locale.ROOT)));}}fm.close();
 }
}
